function Get-HrsConfiguredOdds {
    $odds = [ordered]@{}
    foreach ($biome in $biomes) { $odds[$biome] = 0.0 }
    if (!$randomRadio.Checked) { return $odds }
    $selection = Get-HrsFormSelection
    switch -CaseSensitive ($selection.Selection) {
        'Any' { foreach ($biome in $biomes) { $odds[$biome] = 100.0 / $biomes.Count } }
        'Chosen' { $odds[[string]$chosenCombo.SelectedItem] = 100.0 }
        'Weighted' {
            $total = ($selection.Weights | Measure-Object -Sum).Sum
            if ($total -gt 0) {
                foreach ($biome in $biomes) { $odds[$biome] = 100.0 * [double]$weights[$biome] / $total }
            }
        }
    }
    return $odds
}

function Set-HrsSelectionMethod {
    param([Parameter(Mandatory=$true)][ValidateSet('Any','Chosen','Weighted')][string]$Selection)
    if (@('Any','Chosen','Weighted') -cnotcontains $Selection) { throw 'BIOME_SELECTION_INVALID' }
    if ($script:managerOperation -ne 'Idle') { return }
    $priorLoading = $script:loadingSelection
    $script:loadingSelection = $true
    try {
        $script:selectionMethod = $Selection
        if ($null -ne $script:methodRadios) {
            foreach ($key in @('Any','Chosen','Weighted')) { $script:methodRadios[$key].Checked = $key -ceq $Selection }
        }
    } finally { $script:loadingSelection = $priorLoading }
    if (!$priorLoading) { Update-HrsBiomePreview }
}

function Update-HrsBiomePreview {
    if ($script:loadingSelection) { return }
    $script:managerNotice = ''
    $isRandom = $randomRadio.Checked
    $idle = $script:managerOperation -eq 'Idle'
    $biomeGroup.Visible = $isRandom
    $biomeGroup.Enabled = $isRandom -and $idle
    $forestRequested = $isRandom -and $script:selectionMethod -ceq 'Chosen' -and [string]$chosenCombo.SelectedItem -ceq 'Forest'
    $biomeProtectCheck.Visible = $isRandom -and !$forestRequested
    $biomeProtectCheck.Enabled = $isRandom -and $idle -and !$forestRequested
    $chosenCombo.Visible = $script:selectionMethod -ceq 'Chosen'
    $chosenCombo.Enabled = $isRandom -and $idle -and $script:selectionMethod -ceq 'Chosen'
    $editWeights.Visible = $script:selectionMethod -ceq 'Weighted'
    $editWeights.Enabled = $isRandom -and $idle -and $script:selectionMethod -ceq 'Weighted'
    if ($null -ne $script:weightSummary) {
        $script:weightSummary.Enabled = $script:selectionMethod -ceq 'Weighted'
        $script:weightSummary.Text = ''
        if ($isRandom -and $script:selectionMethod -ceq 'Weighted') {
            $odds = Get-HrsConfiguredOdds
            $script:weightSummary.Text = (@($biomes | ForEach-Object { '{0} {1:0.#}%' -f $_,$odds[$_] }) -join '  /  ')
        }
    }
    Update-HrsStatus
    # Selection changes update scrollable content, never the user's outer size.
    Update-HrsTextWidths
}

