        $control.Dock = 'Top'; $control.Margin = New-Object Windows.Forms.Padding(0,0,0,12)
        $control.TabIndex = $row; $column.Controls.Add($control,0,$row); $row++
    }
    $actions.Margin = New-Object Windows.Forms.Padding(0)
    $updateEditor = {
        $total=0.0
        foreach ($biome in $biomes) { $total += [double]$editControls[$biome].Value }
        foreach ($biome in $biomes) {
            $chance = if ($total -gt 0) { 100.0*[double]$editControls[$biome].Value/$total } else { 0.0 }
            $chanceLabels[$biome].Text = ('{0:N1}% share' -f $chance)
        }
        $save.Enabled = $total -gt 0
    }
    foreach ($biome in $biomes) { $editControls[$biome].Add_ValueChanged($updateEditor) }
    & $updateEditor
    $save.Add_Click({
        foreach ($biome in $biomes) { $weights[$biome] = [int]$editControls[$biome].Value }
        $dialog.DialogResult = [Windows.Forms.DialogResult]::OK
        $dialog.Close()
    })
    $dialog.Add_SystemColorsChanged({param($sender,$eventArgs); Update-HrsPresentationColors -Owner $sender})
    Update-HrsPresentationColors -Owner $dialog
    $dialog.Add_Shown({
        $dialog.PerformLayout()
        $column.PerformLayout()
        $surface.Height = $column.Bottom + $surface.Padding.Bottom
        $frame.PerformLayout()
        $dialog.AutoScrollMinSize = New-Object Drawing.Size(0,($frame.Height+$dialog.AutoScrollMargin.Height))
        $workArea = [Windows.Forms.Screen]::FromControl($dialog).WorkingArea
        $chrome = $dialog.Height - $dialog.ClientSize.Height
        $dialog.Height = [Math]::Min($frame.Height+$chrome+4,$workArea.Height)
        Limit-HrsNormalWindowBounds -Window $dialog
        $dialog.PerformLayout()
        $column.PerformLayout()
        $surface.Height = $column.Bottom + $surface.Padding.Bottom
        $frame.PerformLayout()
        $dialog.AutoScrollMinSize = New-Object Drawing.Size(0,($frame.Height+$dialog.AutoScrollMargin.Height))
    })
    try {
        if ($SmokeTest -and $TestAction -ne 'None') {
            $dialog.Show($form); [Windows.Forms.Application]::DoEvents()
            foreach ($biome in $biomes) { $editControls[$biome].Value=0 }
            if ($save.Enabled) { throw 'EDITOR_ALL_ZERO_NOT_BLOCKED' }
            $editControls['Wasteland'].Value=100
            if (!$save.Enabled) { throw 'EDITOR_POSITIVE_BLOCKED' }
            if ($TestAction -eq 'Save') { $save.PerformClick() } else { $cancel.PerformClick() }
            Update-HrsBiomePreview
            return
        }
        if ($SmokeTest -and $UiScale -ne 1) { $dialog.Scale((New-Object Drawing.SizeF($UiScale,$UiScale))) }
        if (![string]::IsNullOrWhiteSpace($CapturePath)) {
            $dialog.Show($form); [Windows.Forms.Application]::DoEvents()
            $bitmap = New-Object Drawing.Bitmap($dialog.Width,$dialog.Height)
            try { $dialog.DrawToBitmap($bitmap,(New-Object Drawing.Rectangle(0,0,$dialog.Width,$dialog.Height))); $bitmap.Save($CapturePath,[Drawing.Imaging.ImageFormat]::Png) }
            finally { $bitmap.Dispose() }
            $dialog.Close()
            return
        }
        [void]$dialog.ShowDialog($form)
        Update-HrsBiomePreview
    } finally { $dialog.Dispose() }
}


$script:selectionMethod = 'Any'
$script:loadingSelection = $false
$script:managerOperation = 'Idle'
$script:managerConfigurationState = 'Pending'
$standardRadio.Add_CheckedChanged({ if ($standardRadio.Checked -and !$script:loadingSelection) { Update-HrsBiomePreview } })
$randomRadio.Add_CheckedChanged({ if ($randomRadio.Checked -and !$script:loadingSelection) { Update-HrsBiomePreview } })
$chosenCombo.Add_SelectedIndexChanged({ if (!$script:loadingSelection) { Update-HrsBiomePreview } })
$editWeights.Add_Click({ if ($script:managerOperation -eq 'Idle') { Show-WeightEditor } })

$biomeIds = @(3,9,5,1,8)
function Get-HrsFormSelection {
    if (!$randomRadio.Checked) { return @{Selection='Any';ChosenBiome=0;Weights=@(0,0,0,0,0)} }
    switch -CaseSensitive ($script:selectionMethod) {
        'Any' { return @{Selection='Any';ChosenBiome=0;Weights=@(0,0,0,0,0)} }
        'Chosen' {
            if ($chosenCombo.SelectedIndex -lt 0 -or $chosenCombo.SelectedIndex -ge $biomeIds.Count) { throw 'Choose a starting biome.' }
            return @{Selection='Chosen';ChosenBiome=$biomeIds[$chosenCombo.SelectedIndex];Weights=@(0,0,0,0,0)}
        }
        'Weighted' {
            $values = @($biomes | ForEach-Object {
                $value = $weights[$_]
                if ($value -isnot [int] -or $value -lt 0 -or $value -gt 100) { throw 'Biome weights must be whole numbers from 0 to 100.' }
                $value
            })
            return @{Selection='Weighted';ChosenBiome=0;Weights=$values}
        }
        default { throw 'BIOME_SELECTION_INVALID' }
    }
}
function Get-HrsFormDescription {
    $selection = Get-HrsFormSelection
    if (!$randomRadio.Checked) { return 'Standard start' }
    switch -CaseSensitive ($selection.Selection) {
        'Any' { return 'Biome: Any eligible (equal chance)' }
        'Chosen' { return "Biome: $($chosenCombo.SelectedItem)" }
        'Weighted' { return 'Biome weights: ' + (($biomes | ForEach-Object { "$_ $($weights[$_])" }) -join ', ') }
    }
}
function Set-HrsFormFromPolicy {
    param([Parameter(Mandatory=$true)][psobject]$Policy)
    if (@('Standard','Random','RandomSafe') -cnotcontains $Policy.mode) { throw 'POLICY_MODE_INVALID' }
    $savedArgs = Get-HrsSelectionArguments $Policy
    if (@('Any','Chosen','Weighted') -cnotcontains $savedArgs.Selection) { throw 'BIOME_SELECTION_INVALID' }
    $index = -1
    if ($savedArgs.Selection -ceq 'Chosen') {
        $index = @($biomeIds).IndexOf([int]$savedArgs.ChosenBiome)
        if ($index -lt 0) { throw 'CHOSEN_BIOME_INVALID' }
    }
    if ($savedArgs.Selection -ceq 'Weighted') {
        if ($savedArgs.Weights.Count -ne 5) { throw 'BIOME_WEIGHTS_INVALID' }
        foreach ($value in $savedArgs.Weights) {
            if ($value -lt 0 -or $value -gt 100 -or [Math]::Truncate($value) -ne $value) { throw 'BIOME_WEIGHTS_INVALID' }
        }
        if (($savedArgs.Weights | Measure-Object -Sum).Sum -le 0) { throw 'Set at least one biome weight above zero.' }
    }
    $script:loadingSelection = $true
    $form.SuspendLayout()
    try {
        $gameNameBox.Text = $Policy.gameName
        $randomRadio.Checked = $Policy.mode -cne 'Standard'
        $standardRadio.Checked = !$randomRadio.Checked
        # Standard encodes no remembered Random preference. Explicit Random is an opt-out.
        $biomeProtectCheck.Checked = $Policy.mode -cne 'Random'
        Set-HrsSelectionMethod -Selection $savedArgs.Selection
        if ($index -ge 0) { $chosenCombo.SelectedIndex = $index }
        if ($savedArgs.Selection -ceq 'Weighted') { for ($i=0; $i -lt 5; $i++) { $weights[$biomes[$i]] = [int]$savedArgs.Weights[$i] } }
    } finally { $script:loadingSelection = $false; $form.ResumeLayout($true) }
    Update-HrsBiomePreview
}

