function Update-HrsPresentationColors {
    param([switch]$ForceHighContrast,[Windows.Forms.Form]$Owner=$form)
    $highContrast = $ForceHighContrast -or [Windows.Forms.SystemInformation]::HighContrast
    $palette = $script:hrsDesignRecipe.palette
    $Owner.BackColor = if ($highContrast) { [Drawing.SystemColors]::Window } else { [Drawing.ColorTranslator]::FromHtml($palette.background) }
    $Owner.ForeColor = if ($highContrast) { [Drawing.SystemColors]::ControlText } else { [Drawing.ColorTranslator]::FromHtml($palette.text) }
    $queue = New-Object 'Collections.Generic.Queue[Windows.Forms.Control]'
    $queue.Enqueue($Owner)
    while ($queue.Count) {
        $control = $queue.Dequeue()
        if ($control -is [BitWrecked.NativeGraphics.V1.SurfacePanel] -or $control -is [BitWrecked.NativeGraphics.V1.OutlineButton] -or $control -is [BitWrecked.NativeGraphics.V1.StatusBadge]) {
            $control.PreviewHighContrast = [bool]$ForceHighContrast
        }
        if ($control -is [BitWrecked.NativeGraphics.V1.StatusBadge]) {
            # The explicit configuration state owns the badge's semantic colors.
            # Its native control projects system colors when High Contrast is active.
        } elseif ($control -is [Windows.Forms.Label]) {
            $control.BackColor = [Drawing.Color]::Transparent
            $control.ForeColor = if ($highContrast) { [Drawing.SystemColors]::ControlText } elseif ($control.Tag -eq 'Accent') { $script:hrsAccentColor } elseif ($control.Tag -eq 'Muted') { $script:hrsMutedColor } else { $Owner.ForeColor }
            if ($control -is [Windows.Forms.LinkLabel]) {
                $control.LinkColor = if ($highContrast) { [Drawing.SystemColors]::HotTrack } else { $script:hrsMutedColor }
                $control.ActiveLinkColor = if ($highContrast) { [Drawing.SystemColors]::Highlight } else { $script:hrsAccentColor }
                $control.VisitedLinkColor = $control.LinkColor
            }
        } elseif ($control -is [Windows.Forms.TextBox] -or $control -is [Windows.Forms.ComboBox] -or $control -is [Windows.Forms.NumericUpDown]) {
            $control.BackColor = if ($highContrast) { [Drawing.SystemColors]::Window } else { [Drawing.ColorTranslator]::FromHtml($palette.surface) }
            $control.ForeColor = if ($highContrast) { [Drawing.SystemColors]::WindowText } else { $Owner.ForeColor }
        } elseif ($control -is [BitWrecked.NativeGraphics.V1.OutlineButton]) {
            $control.ForeColor = if ($highContrast) { [Drawing.SystemColors]::ControlText } elseif ($control.Tag -eq 'Quiet') { $script:hrsMutedColor } else { $Owner.ForeColor }
        } elseif ($control -is [Windows.Forms.TableLayoutPanel] -or $control -is [Windows.Forms.FlowLayoutPanel]) {
            $control.BackColor = if ($highContrast) { [Drawing.SystemColors]::Control } else { [Drawing.Color]::Transparent }
        } elseif ($control -is [Windows.Forms.CheckBox] -or $control -is [Windows.Forms.RadioButton]) {
            $control.BackColor = [Drawing.Color]::Transparent
            $control.ForeColor = $Owner.ForeColor
        }
        foreach ($child in $control.Controls) { $queue.Enqueue($child) }
    }
    $Owner.Invalidate($true)
}

