function Update-HrsTextWidths {
    if ($null -eq $script:managerLayout -or $script:managerLayoutUpdating -or $form.IsDisposed) { return }
    $script:managerLayoutUpdating = $true
    $scrollPosition = $form.AutoScrollPosition
    try {
        # A scrollbar changes the usable width; wrapping then changes height.
        # Settle that feedback before publishing the explicit vertical extent.
        $previous = ''
        for ($pass = 0; $pass -lt 8; $pass++) {
            $form.PerformLayout()
            $script:managerFrame.PerformLayout()
            $available = [Math]::Max(1,$script:managerLayout.ClientSize.Width - $script:managerLayout.Padding.Horizontal - 6)
            $labels = if ($null -ne $script:managerWrapLabels) { $script:managerWrapLabels } else { @($script:managerIntro,$gameNameHelp,$script:modeNote,$biomeNote,$resultStatus,$script:resultSummary,$details,$status,$script:nextAction) }
            foreach ($label in $labels) {
                if ($null -ne $label -and $null -ne $label.Parent) { $label.MaximumSize = New-Object Drawing.Size($available,0) }
            }
            if ($null -ne $script:managerHeader -and $null -ne $script:managerHeaderTitle) {
                $header = $script:managerHeader
                $titleWidth = $header.ClientSize.Width - $header.Padding.Horizontal
                foreach ($child in $header.Controls) {
                    if ($child -ne $script:managerHeaderTitle) { $titleWidth -= $child.Width + $child.Margin.Horizontal }
                }
                $titleWidth -= $script:managerHeaderTitle.Margin.Horizontal
                $script:managerHeaderTitle.MaximumSize = New-Object Drawing.Size(([Math]::Max(1,$titleWidth)),0)
                $header.PerformLayout()
            } elseif ($null -ne $title -and $null -ne $title.Parent) {
                $title.MaximumSize = New-Object Drawing.Size($available,0)
            }
            if ($null -ne $script:biomeChoices) {
                $choiceWidth = [Math]::Max(1,$script:biomeChoices.ClientSize.Width - $script:biomeChoices.Padding.Horizontal - 6)
                $choiceLabels = if ($null -ne $script:managerChoiceWrapLabels) { $script:managerChoiceWrapLabels } else { @($selectionNote,$script:weightSummary) }
                foreach ($label in $choiceLabels) {
                    if ($null -ne $label -and $null -ne $label.Parent) { $label.MaximumSize = New-Object Drawing.Size($choiceWidth,0) }
                }
                $script:biomeChoices.PerformLayout()
                $biomeGroup.Height = $script:biomeChoices.Bottom + $biomeGroup.Padding.Bottom
            }
            $script:managerLayout.PerformLayout()
            $script:managerSurface.Height = $script:managerLayout.Bottom + $script:managerSurface.Padding.Bottom
            $script:managerFrame.PerformLayout()
            # Frame.Top is shifted by AutoScrollPosition. Recover its logical
            # coordinate so scrolling itself cannot shrink the virtual area.
            $logicalTop = $script:managerFrame.Top - $form.AutoScrollPosition.Y
            $extent = [Math]::Max(0,$logicalTop + $script:managerFrame.Height + $script:managerFrame.Margin.Bottom + $form.AutoScrollMargin.Height)
            $form.AutoScrollMinSize = New-Object Drawing.Size(0,$extent)
            $form.PerformLayout()
            $current = '{0}/{1}/{2}/{3}/{4}' -f $script:managerLayout.Width,$script:managerLayout.Height,$script:managerFrame.Height,$form.ClientSize.Width,$extent
            if ($current -ceq $previous) { break }
            $previous = $current
        }
        # AutoSize layout can scroll the focused child into view. Preserve the
        # user's scroll position while recomputing the virtual extent; WinForms
        # clamps the restored position to the new valid range automatically.
        $form.AutoScrollPosition = New-Object Drawing.Point(0,(-$scrollPosition.Y))
    } finally { $script:managerLayoutUpdating = $false }
}

function Limit-HrsNormalWindowBounds {
    param([Windows.Forms.Form]$Window=$form)
    if (!$Window.Visible -or $Window.IsDisposed -or $Window.WindowState -ne [Windows.Forms.FormWindowState]::Normal) { return }
    $workArea = [Windows.Forms.Screen]::FromControl($Window).WorkingArea
    $width = [Math]::Min($Window.Width,$workArea.Width)
    $height = [Math]::Min($Window.Height,$workArea.Height)
    $left = [Math]::Max($workArea.Left,[Math]::Min($Window.Left,$workArea.Right-$width))
    $top = [Math]::Max($workArea.Top,[Math]::Min($Window.Top,$workArea.Bottom-$height))
    $Window.SetBounds($left,$top,$width,$height)
}

function Fit-HrsManagerWindow {
    if (!$form.Visible -or $form.IsDisposed -or $form.WindowState -ne [Windows.Forms.FormWindowState]::Normal -or $script:managerFitting) { return }
    $script:managerFitting = $true
    try {
        Update-HrsTextWidths
        if (!$script:managerUserResized) {
            $workArea = [Windows.Forms.Screen]::FromControl($form).WorkingArea
            $chrome = $form.Height - $form.ClientSize.Height
            $desired = $script:managerFrame.Height + $form.AutoScrollMargin.Height + 4 + $chrome
            $height = [Math]::Max($form.MinimumSize.Height,[Math]::Min($desired,$workArea.Height))
            # Never feed scrollbar-reduced ClientSize.Width back into a size
            # assignment. Changing only outer Height preserves outer Width.
            $form.Height = $height
        }
        Limit-HrsNormalWindowBounds
        Update-HrsTextWidths
        if ($script:managerGeometryWindowState -eq [Windows.Forms.FormWindowState]::Normal -and !$script:managerRestoreQueued) { $script:managerNormalBounds = $form.Bounds }
    } finally { $script:managerFitting = $false }
}

function Initialize-HrsManagerGeometryEvents {
    $script:managerGeometryWindowState = $form.WindowState
    $script:managerNormalBounds = $form.Bounds
    $form.Add_Resize({
        if ($script:managerRestoringBounds) { return }
        $state = $form.WindowState
        if ($state -eq [Windows.Forms.FormWindowState]::Normal) {
            if ($script:managerGeometryWindowState -ne [Windows.Forms.FormWindowState]::Normal -and $null -ne $script:managerNormalBounds -and !$script:managerRestoreQueued) {
                # .NET Framework may save scrollbar-reduced client width when
                # restoring a scrollable form. Finish the native state change
                # first, then restore the recorded outer bounds once.
                $script:managerRestoreQueued = $true
                [void]$form.BeginInvoke([Action]{
                    try {
                        if ($form.IsDisposed -or $form.WindowState -ne [Windows.Forms.FormWindowState]::Normal) { return }
                        $script:managerRestoringBounds = $true
                        $form.Bounds = $script:managerNormalBounds
                        Limit-HrsNormalWindowBounds
                        Update-HrsTextWidths
                        $script:managerNormalBounds = $form.Bounds
                    } finally { $script:managerRestoringBounds = $false; $script:managerRestoreQueued = $false }
                })
            }
        }
        $script:managerGeometryWindowState = $state
        Update-HrsTextWidths
    })
    $form.Add_ResizeBegin({
        $script:managerResizeBeginSize = $form.Size
    })
    $form.Add_ResizeEnd({
        if ($null -ne $script:managerResizeBeginSize -and $form.Size -ne $script:managerResizeBeginSize) { $script:managerUserResized = $true }
        $script:managerResizeBeginSize = $null
        Fit-HrsManagerWindow
        if ($form.WindowState -eq [Windows.Forms.FormWindowState]::Normal) { $script:managerNormalBounds = $form.Bounds }
    })
    $form.Add_ClientSizeChanged({ Update-HrsTextWidths })
    $form.Add_Activated({ Limit-HrsNormalWindowBounds; Update-HrsTextWidths })
}

