function Test-HrsFormMatchesPolicy {
    param([psobject] $Policy)
    if ($null -eq $Policy) { return $false }
    $mode = if (!$randomRadio.Checked) { 'Standard' } elseif ($biomeProtectCheck.Checked) { 'RandomSafe' } else { 'Random' }
    if (![string]::Equals($gameNameBox.Text,$Policy.gameName,[StringComparison]::Ordinal) -or $mode -cne $Policy.mode) { return $false }
    $formSelection = Get-HrsFormSelection
    $savedSelection = Get-HrsSelectionArguments -Policy $Policy
    return ($formSelection.Selection -ceq $savedSelection.Selection -and
        $formSelection.ChosenBiome -eq $savedSelection.ChosenBiome -and
        ($formSelection.Weights -join ',') -ceq ($savedSelection.Weights -join ','))
}



function Get-HrsNameHelp {
    param([string] $Reason)
    switch ($Reason) {
        'GAME_NAME_REQUIRED' { 'Enter the Game Name for the save you want to configure.' }
        'GAME_NAME_OUTER_WHITESPACE' { 'Remove spaces at the beginning or end of the Game Name.' }
        'GAME_NAME_TOO_LONG' { 'Use a Game Name of 64 characters or fewer.' }
        'GAME_NAME_TRAILING_DOT' { 'Remove the dot at the end of the Game Name.' }
        'GAME_NAME_NONCANONICAL' { 'Retype the Game Name using standard characters.' }
        default { 'Use a valid save name without reserved names or characters.' }
    }
}


function Set-HrsOperationControls {
    param([bool]$Enabled)
    foreach ($control in @($gameNameBox,$standardRadio,$randomRadio,$biomeGroup,$biomeProtectCheck)) { $control.Enabled = $Enabled }
    if (!$Enabled) { foreach ($control in @($applyButton,$launchButton,$uninstallButton,$editWeights,$chosenCombo)) { $control.Enabled = $false } }
    if ($null -ne $script:helpLink) { $script:helpLink.Enabled = $Enabled }
    if ($null -ne $script:checkSettingsButton) { $script:checkSettingsButton.Enabled = $Enabled }
}

# Shared, read-only disk assessment. Known paths are validated before identity reads;
# policy and inventory are assessed separately even for missing/legacy/invalid policy.
function Get-HrsSettingsReadStamp {
    $pathCheck = Test-HrsBridgePaths -GameRoot $gameRoot
    if (!$pathCheck.Valid) { throw $pathCheck.Reason }
    $paths = $pathCheck.Paths
    $stamps = @()
    $members = New-Object Collections.Generic.List[string]
    $pending = New-Object Collections.Generic.Queue[string]
    if ([IO.Directory]::Exists($paths.ReleaseRoot)) { $pending.Enqueue($paths.ReleaseRoot) }
    while ($pending.Count -gt 0) {
        $directory = $pending.Dequeue()
        if (([IO.File]::GetAttributes($directory) -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'SETTINGS_PATH_UNSAFE' }
        foreach ($entryPath in [IO.Directory]::EnumerateFileSystemEntries($directory)) {
            $attributes = [IO.File]::GetAttributes($entryPath)
            if (($attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'SETTINGS_PATH_UNSAFE' }
            $isDirectory = ($attributes -band [IO.FileAttributes]::Directory) -ne 0
            [void]$members.Add($(if ($isDirectory) { 'D:' } else { 'F:' }) + $entryPath.Substring($paths.ReleaseRoot.Length))
            if ($isDirectory) { $pending.Enqueue($entryPath) }
        }
    }
    foreach ($file in @((Join-Path $paths.ReleaseRoot 'd0163.dll'),(Join-Path $paths.ReleaseRoot 'ModInfo.xml'),$paths.PolicyPath,$paths.LegacyPolicyPath,$paths.ResultPath)) {
        if ([IO.File]::Exists($file) -and (([IO.File]::GetAttributes($file) -band [IO.FileAttributes]::ReparsePoint) -ne 0)) { throw 'SETTINGS_PATH_UNSAFE' }
        $stamps += if ([IO.File]::Exists($file)) { (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash } else { 'ABSENT' }
    }
    return ($stamps -join '|') + '::' + (@($members | Sort-Object) -join '|')
}

function Get-HrsSettingsAssessment {
    $answer = [pscustomobject]@{ Policy=$null; PolicyState='Invalid'; PolicyReason=''; Inventory=$null; InstallationValid=$false; InstallationReason=''; NameMatches=$false; FormMatches=$false; Consistent=$false }
    try {
        $before = Get-HrsSettingsReadStamp
        try {
            $answer.Policy = Read-HrsConfiguredPolicy -GameRoot $gameRoot
            $answer.PolicyState = if ($null -eq $answer.Policy) { 'Missing' } elseif ($answer.Policy.schema -ceq 'hrs-policy/v1') { 'Legacy' } else { 'Current' }
        } catch { $answer.PolicyReason = $_.Exception.Message }
        try {
            $manifest = $script:appliedManifest
            if (!$useDevCandidate -or $null -eq $manifest) {
                foreach ($entry in @(@('d0163.dll',$verifiedRuntimeSha256),@('ModInfo.xml',$verifiedModInfoSha256))) {
                    $file = Join-Path $verifiedPayloadRoot $entry[0]
                    if (![IO.File]::Exists($file) -or (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash -cne $entry[1]) { throw 'Verified mod payload changed. Redownload the mod package.' }
                }
                $manifest = New-HrsDeploymentManifest -PayloadRoot $verifiedPayloadRoot -ReleaseVersion '1.3.0'
            }
            $answer.Inventory = Test-HrsDeploymentInventory -GameRoot $gameRoot -Manifest $manifest
            $answer.InstallationValid = $answer.Inventory.Valid -and $answer.Inventory.State -ceq 'InstalledValid'
            $answer.InstallationReason = $answer.Inventory.Reason
        } catch { $answer.InstallationReason = $_.Exception.Message }
        $after = Get-HrsSettingsReadStamp
        if ($before -cne $after) { throw 'SETTINGS_CHANGED_DURING_CHECK' }
        $answer.Consistent = $true
        if ($null -ne $answer.Policy) {
            $answer.NameMatches = [string]::Equals($gameNameBox.Text,$answer.Policy.gameName,[StringComparison]::Ordinal)
            $answer.FormMatches = Test-HrsFormMatchesPolicy -Policy $answer.Policy
        }
    } catch {
        $answer.Consistent = $false; $answer.InstallationValid = $false
        $answer.PolicyReason = $_.Exception.Message; $answer.InstallationReason = $_.Exception.Message
    }
    return $answer
}

function Get-HrsCheckSettingsPolicyText {
    param([psobject]$Assessment)
    $name = $gameNameBox.Text
    if (!$Assessment.Consistent -or $Assessment.PolicyState -ceq 'Invalid') { return "Cannot verify settings for '$name'. Check Game details and keep the diagnostic for support." }
    if ($Assessment.PolicyState -ceq 'Missing') { return "No settings are saved for '$name'. Choose your options and use Apply Settings. The save does not need to exist yet." }
    if ($Assessment.PolicyState -ceq 'Legacy') { return "Earlier settings target '$($Assessment.Policy.gameName)'. Use Apply Settings to update them for '$name'." }
    if (!$Assessment.NameMatches) { return "Saved settings target '$($Assessment.Policy.gameName)', not '$name'. Use Apply Settings to configure this name." }
    if (!$Assessment.FormMatches) { return "Saved settings target '$name' with different options. Use Apply Settings to save your selected options." }
    if (!$Assessment.InstallationValid) { return "Settings for '$name' are saved, but the installed mod files are not verified. Use Apply Settings; check Game details if it cannot complete." }
    if ($script:launchBlockedUntilApply) { return "Saved settings and mod files match '$name'. Launch remains blocked: apply successfully and acknowledge Settings Applied." }
    return "Saved settings and verified mod files match '$name'. This checks configuration, not save existence, character eligibility or a completed start."
}

function Get-HrsCheckSettingsText {
    param([psobject]$Assessment)
    $text = Get-HrsCheckSettingsPolicyText -Assessment $Assessment
    if ($Assessment.Consistent -and $null -eq $Assessment.Inventory -and $Assessment.InstallationReason) {
        $target = if ($null -ne $Assessment.Policy) { " Saved settings target '$($Assessment.Policy.gameName)'." } else { '' }
        $text = "Cannot verify mod files for '$($gameNameBox.Text)'.$target`r`n`r`n" + (Get-HrsCustomerErrorText -Detail $Assessment.InstallationReason)
    }
    elseif ($Assessment.Consistent -and !$Assessment.Inventory.Valid -and $Assessment.InstallationReason -cne 'DEPLOYMENT_STATIC_FILE_DRIFT') {
        $target = if ($null -ne $Assessment.Policy) { " Saved settings target '$($Assessment.Policy.gameName)'." } else { '' }
        $text = "Cannot verify installed mod files for '$($gameNameBox.Text)'.$target Keep the Game details diagnostic for support before changing files."
    }
    elseif ($Assessment.Consistent -and !$Assessment.Inventory.Valid -and $text -notmatch 'not verified|Cannot verify') {
        $text += "`r`n`r`nInstalled mod files also need verification. Use Apply Settings and check Game details if it cannot complete."
    }
    return $text
}

function Invoke-HrsCheckSettings {
    if ($script:managerOperation -cne 'Idle') { return }
    $nameCheck = Test-HrsExactGameName -GameName $gameNameBox.Text
    if (!$nameCheck.Valid) { $text = Get-HrsNameHelp -Reason $nameCheck.Reason }
    else {
        $assessment = Get-HrsSettingsAssessment
        Update-HrsStatus -Assessment $assessment
        $text = Get-HrsCheckSettingsText -Assessment $assessment
        if ((Get-HrsProcessState).Game -cne 'Closed') { $text += "`r`n`r`nFiles currently on disk only. This cannot confirm what a running player loaded." }
    }
    # No retained comparison: this popup is a point-in-time read; edits use fresh state.
    [void][Windows.Forms.MessageBox]::Show($form,$text,'Check settings',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Information)
}

function Get-HrsCustomerErrorText {
    param([string]$Detail)
    if ($Detail -match 'APPLY_RECOVERY_FAILED|recovery could not be verified') { return 'Settings could not be applied, and recovery could not be verified. Keep the backup and Game details diagnostic for support.' }
    if ($Detail -match 'APPLY_ROLLED_BACK|returned to their previous state') { return 'Settings could not be applied. Previous installation files were restored and verified. Review Game details before trying again.' }
    if ($Detail -match 'STEAM_NOT_RUNNING|STEAM_STATE_UNCONFIRMED') { return 'Open Steam, then try Launch Game again.' }
    if ($Detail -match 'GAME_ALREADY_RUNNING|GAME_STATE_UNCONFIRMED') { return 'Close 7 Days to Die, then try again.' }
    if ($Detail -match 'payload|runtime hash|ModInfo hash|ModInfo identity') { return 'The mod package could not be verified. Redownload and extract the complete mod package.' }
    if ($Detail -match 'POLICY_|BRIDGE_|SETTINGS_CHANGED|SETTINGS_PATH') { return 'Saved settings could not be verified. Keep the Game details diagnostic for support before changing files.' }
    if ($Detail -match 'LAUNCH_INSTALLATION_INVALID|DEPLOYMENT_|Release destination|Release upgrade|ownership|confirmed as') { return 'The installed mod files could not be verified. Review Game details and use Apply Settings when the game is closed.' }
    if ($Detail -match '(?-i:\b[A-Z][A-Z0-9_]{3,}\b)|Access.*denied|INJECTED_|MANAGER_|ATOMIC_|CORE_|REMOVAL_') { return 'The operation could not finish. Check the game folder and permissions; keep the Game details diagnostic for support.' }
    return $Detail
}

function Start-HrsManagerOperation {
    param([ValidateSet('Applying','Uninstalling')][string]$Operation)
    if ($script:managerOperation -ne 'Idle') { throw 'HRS_OPERATION_BUSY' }
    $script:managerOperation = $Operation
    Set-HrsOperationControls $false
    Update-HrsStatus
    $form.Refresh()
}

function Render-HrsConfigurationState {
    if ($null -eq $script:applyBadge) { return }
    $palette = $script:hrsDesignRecipe.palette
    $applied = $script:managerConfigurationState -ceq 'Applied'
    $prefix = if ($applied) { 'applied' } else { 'pending' }
    $script:applyBadge.Text = switch ($script:managerOperation) {
        'Applying' { 'Applying settings...' }
        'AwaitingAcknowledgement' { 'Awaiting acknowledgement.' }
        'Uninstalling' { 'Uninstalling...' }
        default { if ($applied) { 'Changes applied.' } else { 'Changes not applied.' } }
    }
    $script:applyBadge.FillColor = [Drawing.ColorTranslator]::FromHtml($palette.($prefix+'Fill'))
    $script:applyBadge.BorderColor = [Drawing.ColorTranslator]::FromHtml($palette.($prefix+'Border'))
    $script:applyBadge.ForeColor = [Drawing.ColorTranslator]::FromHtml($palette.($prefix+'Text'))
    $script:applyBadge.AccentColor = [Drawing.ColorTranslator]::FromHtml($palette.($prefix+'Dot'))
    $script:applyBadge.ShowAccent = $true
    $script:applyBadge.AccessibleName = $script:applyBadge.Text
    $script:applyBadge.Size = $script:applyBadge.GetPreferredSize([Drawing.Size]::Empty)
}

function Get-HrsCurrentOperationError {
    param([psobject]$Process,[bool]$Matches,[psobject]$Saved)
    if ($script:managerErrorAction -cne 'Launch' -or !$script:managerError) { return $script:managerError }
    $detail = $script:managerError.Substring('Launch blocked: '.Length)
    $resolved = switch -CaseSensitive ($detail) {
        'STEAM_NOT_RUNNING' { $Process.Steam -ceq 'Running' }
        'STEAM_STATE_UNCONFIRMED' { $Process.Steam -ceq 'Running' }
        'GAME_ALREADY_RUNNING' { $Process.Game -ceq 'Closed' }
        'GAME_STATE_UNCONFIRMED' { $Process.Game -ceq 'Closed' }
        'Changes not applied. Select Apply Settings before launching.' { $Matches }
        'Apply Settings successfully and acknowledge Settings Applied before launching.' { !$script:launchBlockedUntilApply }
        'Apply Settings before launching. Enter the exact game name, choose your settings, then click Apply Settings.' {
            $null -ne $Saved -and $Saved.schema -ceq 'hrs-policy/v2'
        }
        default {
            if ($detail.StartsWith('LAUNCH_INSTALLATION_INVALID:',[StringComparison]::Ordinal) -or
                $detail -ceq 'Verified mod payload changed. Redownload the mod package.') { $script:managerInstallationValid }
            else { $false }
        }
    }
    if ($resolved) { return '' }
    return $script:managerError
}

function Update-HrsStatus {
    param([switch]$RefreshInstallation,[psobject]$Assessment=$null)
    if (!$script:managerInitialized -or $script:loadingSelection) { return }
    $applyButton.Enabled = $false
    $launchButton.Enabled = $false
    $uninstallButton.Enabled = $false
    if ($script:managerOperation -ne 'Idle') {
        Set-HrsOperationControls $false
        $script:managerConfigurationState = 'Pending'
        $status.Text = switch ($script:managerOperation) {
            'Applying' { 'Applying settings...' }
            'AwaitingAcknowledgement' { 'Settings verified. Acknowledge Settings Applied to continue.' }
            'Uninstalling' { 'Removing HRS-owned files...' }
        }
        $script:nextAction.Text = ''
        $script:nextAction.Visible = $false
        $status.Visible = $true
        Render-HrsConfigurationState
        Update-HrsTextWidths
        return
    }
    Set-HrsOperationControls $true
    $script:managerConfigurationState = 'Pending'
    $readyText = ''
    $nextText = ''
    $script:managerStatusError = ''
    $script:managerUninstallReason = ''
    $currentOperationError = $script:managerError
    try {
        $process = Get-HrsProcessState
        $currentOperationError = Get-HrsCurrentOperationError -Process $process -Matches $false -Saved $null
        if ($null -eq $Assessment) { $Assessment = Get-HrsSettingsAssessment }
        $saved = $Assessment.Policy
        $script:managerInstallationValid = $Assessment.Consistent -and $Assessment.InstallationValid
        $script:managerInstallationReason = $Assessment.InstallationReason
        if (!$Assessment.Consistent -or $Assessment.PolicyState -ceq 'Invalid') { throw $Assessment.PolicyReason }
        $matches = $Assessment.FormMatches
        $currentOperationError = Get-HrsCurrentOperationError -Process $process -Matches $matches -Saved $saved
        if ($matches -and $null -ne $saved) {
            $script:managerConfigurationState = if ($saved.schema -ceq 'hrs-policy/v2' -and $script:managerInstallationValid -and !$script:launchBlockedUntilApply -and (!$useDevCandidate -or $null -ne $script:appliedManifest)) { 'Applied' } else { 'Saved' }
        }
        # Availability is a fresh read-only ownership assessment, not folder existence.
        $ownership = Test-HrsRemovalOwnership -GameRoot $gameRoot
        $canRemove = $ownership.Valid -and $ownership.State -ceq 'Owned'
        $script:managerUninstallReason = if ($canRemove) { 'Remove HRS-owned files; saves and unrelated files are preserved.' } elseif ($ownership.State -ceq 'NotInstalled') { 'HRS is not installed.' } else { 'Installed files could not be identified as HRS. Keep the Game details diagnostic before changing files.' }
        if ($process.Game -ne 'Closed') {
            $readyText = if ($process.Game -eq 'Running') { 'Close 7 Days to Die before applying settings or uninstalling.' } else { 'Game state unavailable. Close 7 Days to Die and return here.' }
            $script:managerUninstallReason = $readyText
        } else {
            $nameCheck = Test-HrsExactGameName -GameName $gameNameBox.Text
            $selection = Get-HrsFormSelection
            $validWeights = $selection.Selection -cne 'Weighted' -or ($selection.Weights | Measure-Object -Sum).Sum -gt 0
            $applyButton.Enabled = $nameCheck.Valid -and $validWeights
            $uninstallButton.Enabled = $canRemove
            $launchButton.Enabled = $script:managerConfigurationState -ceq 'Applied' -and $process.Steam -ceq 'Running'
            if (!$nameCheck.Valid) { $nextText = Get-HrsNameHelp -Reason $nameCheck.Reason }
            elseif (!$validWeights) { $nextText = 'Set at least one biome weight above zero.' }
            elseif ($script:managerConfigurationState -ceq 'Saved' -or $script:managerConfigurationState -ceq 'Pending') {
                # Ordinary restored and edited settings share the compact pending badge.
                # Conflicting/unsafe ownership still gets an actionable visible blocker.
                if (!$ownership.Valid -or $ownership.State -cnotin @('Owned','NotInstalled')) { $nextText = $script:managerUninstallReason }
            }
            elseif ($process.Steam -ne 'Running') { $nextText = if ($process.Steam -eq 'Closed') { 'Open Steam to launch the game.' } else { 'Steam state unavailable. Open Steam and return here.' } }
        }
    } catch {
        $script:managerStatusError = "Settings blocked: $($_.Exception.Message)"
        $script:managerConfigurationState = 'Blocked'
        $nextText = 'Keep the Game details diagnostic for support before changing files.'
        $applyButton.Enabled = $false; $launchButton.Enabled = $false; $uninstallButton.Enabled = $false
    }
    $status.Text = if ($currentOperationError) { Get-HrsCustomerErrorText $currentOperationError } elseif ($script:managerStatusError) { Get-HrsCustomerErrorText $script:managerStatusError } elseif ($script:managerNotice) { $script:managerNotice } else { $readyText }
    $status.Visible = ![string]::IsNullOrEmpty($status.Text)
    $script:nextAction.Text = $nextText
    $script:nextAction.Visible = ![string]::IsNullOrEmpty($nextText)
    if ($null -ne $script:managerStatePanel) { $script:managerStatePanel.Visible = $status.Visible -or $script:nextAction.Visible }
    $uninstallButton.AccessibleDescription = $script:managerUninstallReason
    $details.Text = "Game folder:`r`n$gameRoot`r`n`r`nRemoval: $script:managerUninstallReason"
    if ($script:managerInstallationReason) { $details.Text += "`r`nInstallation: $script:managerInstallationReason" }
    if ($script:managerError) { $details.Text += "`r`nDiagnostic: $script:managerError" }
    if ($script:managerStatusError) { $details.Text += "`r`nValidation: $script:managerStatusError" }
    if ($script:managerHistoryDiagnostic) { $details.Text += "`r`nRecovery history: $script:managerHistoryDiagnostic" }
    if ($null -ne $ownership -and $ownership.Reason) { $details.Text += "`r`nOwnership: $($ownership.Reason)" }
    if ($null -ne $script:lastOperationDurationMs) { $details.Text += ('`r`nLast processing duration: {0:0.#} ms' -f $script:lastOperationDurationMs).Replace('`r`n',"`r`n") }
    $chosenCombo.Enabled = $randomRadio.Checked -and $script:selectionMethod -ceq 'Chosen'
    $editWeights.Enabled = $randomRadio.Checked -and $script:selectionMethod -ceq 'Weighted'
    $biomeGroup.Enabled = $randomRadio.Checked
    $biomeProtectCheck.Enabled = $randomRadio.Checked
    Render-HrsConfigurationState
    Update-HrsResultStatus
    Update-HrsTextWidths
}

function Show-HrsHelp {
    if ($script:managerOperation -ne 'Idle') { return }
    $help = New-Object Windows.Forms.Form
    $help.Text = 'New Player Random Start - Help'
    $help.Icon = $form.Icon; $help.Font = $form.Font
    $help.StartPosition = 'CenterParent'; $help.Size = New-Object Drawing.Size(580,540)
    $help.MinimumSize = New-Object Drawing.Size(340,300)
    $help.MaximizeBox = $false
    $body = New-Object Windows.Forms.TextBox
    $body.Multiline = $true; $body.ReadOnly = $true; $body.ScrollBars = 'Vertical'
    $body.Dock = 'Fill'; $body.BackColor = [Drawing.SystemColors]::Window
    $body.AccessibleName = 'Setup help, biome choices, protection limits and first-session instruction'
    $body.Text = @'
Game Name
Enter the save's exact Game Name, not the world's name. Before the save exists, choose its name here, Apply Settings, then create the game with that exact name. Apply does not create or require a save. A restored name is your previous configuration, not a shipped default or proof a fresh character is ready. You can use a supported existing world. Random placement happens on a fresh character's first spawn; loading an already-played character does not give it a new random start.

Check settings
Read current settings and mod files without applying, repairing or changing your draft. Name agreement alone is not complete agreement. This checks files on disk, not save existence, what a live player loaded, a completed start or trader assignment. Apply and Launch perform their own fresh checks.

Biome choices
Any gives equal chances among eligible biomes. Choose requests one biome. Custom weights are relative whole numbers from 0 to 100: zero excludes a biome and at least one weight must be positive. Shares are previews; world availability and placement safety affect the outcome. Random selections can repeat.

Starting biome hazard protection
Protection defaults on when no saved Random preference exists. Uncheck it for a challenge run. It covers recognized environmental hazards in the starting biome only. Enemies, hazards in other biomes and unrecognized effects remain active. Explicit Forest hides this choice without changing your preference: a fresh Forest landing has no recognized HRS starting-hazard protection to apply. Earlier protection on a completed character's original hazardous landing is preserved. Standard does not save a separate Random preference.

Apply and launch
Apply Settings installs, saves and verifies the configuration. Settings Applied acknowledges completed work. Launch Game starts the game separately; Steam must be running and the game must be closed. If no safe landing is available, HRS keeps the usual start.

First Random session
Do not log out until your first trader is assigned. Complete the opening tasks in this session and wait for the Journey to Settlement trader marker. Leaving earlier may send the quest to Pine Forest when you return. You can visit the trader later. Your landing remains saved. A valid fallback can also select a trader in another biome.

Setup and removal
Windows PowerShell 5.1, local single-player. Navezgane; for Random Gen, use worlds of 8192 or larger. Keep EAC disabled and the supplied 0_TFP_Harmony. Extract the whole package to a writable local folder outside synced or linked folders, then run START.bat. Uninstall removes HRS-owned files; saves, player progress and unrelated files remain. It does not reset a saved landing or quest.
'@
    $close = New-Object Windows.Forms.Button
    $close.Text = 'Close'; $close.Dock = 'Bottom'; $close.Height = 36
    $close.DialogResult = [Windows.Forms.DialogResult]::OK
    $help.Controls.Add($body); $help.Controls.Add($close)
    $help.AcceptButton = $close; $help.CancelButton = $close
    $help.Add_Shown({ Limit-HrsNormalWindowBounds -Window $help; $body.Select(0,0); $body.Focus() })
    try { [void]$help.ShowDialog($form) } finally { $help.Dispose() }
}

function Get-HrsApplyErrorText {
    param([string]$Detail)
    if ($Detail.StartsWith('APPLY_ROLLED_BACK:',[StringComparison]::Ordinal)) {
        return 'Settings could not be applied. Previous installation files were restored and verified. Review Game details before trying again.'
    }
    if ($Detail.StartsWith('APPLY_RECOVERY_FAILED:',[StringComparison]::Ordinal)) {
        $backup = [regex]::Match($Detail,'backup: ([^;]+)').Groups[1].Value
        return ("Settings could not be applied, and recovery could not be verified. Keep the backup and Game details diagnostic for support." + $(if ($backup) { "`r`n`r`nBackup: $backup" } else { '' }))
    }
    return Get-HrsCustomerErrorText -Detail $Detail
}

function Update-HrsResultStatus {
    try {
        $currentResult = Get-HrsCurrentResultState -GameRoot $gameRoot
        if ($currentResult.State -eq 'Current') {
            $appliedName = $currentResult.Policy.gameName
            $previous = !(Test-HrsFormMatchesPolicy -Policy $currentResult.Policy) -or !$script:managerInstallationValid
            $attribution = if ($previous) { "Previous applied settings for '$appliedName'" } else { "Last recorded start for '$appliedName'" }
            $resultStatus.Text = "$($attribution): $($currentResult.Result.outcome) / $($currentResult.Result.reason)"
            $summary = switch ($currentResult.Result.outcome) {
                'COMPLETED' { 'Random start completed.' }
                'BYPASSED' { 'Standard start used.' }
                'RESERVED' { 'Placement pending.' }
                'FAILED' { 'Random start did not complete.' }
                'INCOMPATIBLE' {
                    if ($currentResult.Result.reason -eq 'BUILD_MISMATCH') { 'HRS could not run with this game build.' }
                    else { 'HRS could not run. See Game details.' }
                }
                default { 'HRS start was skipped. See Game details.' }
            }
            $script:resultSummary.Text = $attribution + ': ' + $summary
        }
        elseif ($currentResult.State -eq 'Stale') {
            $resultStatus.Text = 'Earlier applied settings; no result for the current revision'
            $script:resultSummary.Text = 'Last recorded start: earlier applied settings.'
        }
        else {
            $resultStatus.Text = 'Last start: no result for the current settings'
            $script:resultSummary.Text = if ($currentResult.State -eq 'Unconfigured') { 'Last start: no applied settings.' } else { 'Last start: no result for applied settings.' }
        }
    }
    catch {
        $resultStatus.Text = 'Last start result unavailable or invalid'
        $script:resultSummary.Text = 'Last start: result unavailable. See Game details.'
    }
}

function Get-HrsGameBuildNotice {
    $assemblyPath = Join-Path $gameRoot '7DaysToDie_Data\Managed\Assembly-CSharp.dll'
    if (-not [IO.File]::Exists($assemblyPath)) {
        throw 'Game compatibility check failed: Assembly-CSharp.dll was not found.'
    }
    if ((Get-FileHash -Algorithm SHA256 -LiteralPath $assemblyPath).Hash -cne $verifiedAssemblyCSharpSha256) {
        return $unverifiedGameBuildMessage
    }
    # The full-file fingerprint identifies the tested assembly, including its MVID,
    # without loading/caching or locking game DLLs in the manager process.
    return ''
}

function Initialize-HrsManagerStorage {
    $probe = $null
    try {
        $statePaths = Initialize-HrsManagerState -ManagerRoot $managerRoot
        $probe = Join-Path $statePaths.StateRoot ('.write-check-' + [guid]::NewGuid().ToString('N'))
        $stream = [IO.File]::Open($probe, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
        $stream.Dispose()
        [IO.File]::Delete($probe)
        $probe = $null
    }
    catch {
        throw 'HRS cannot save recovery settings in this folder. Move the entire extracted HRS folder to a writable local folder outside OneDrive or other synced or linked folders, reopen START.bat, and apply again. No game files were changed.'
    }
    finally {
        if ($null -ne $probe -and [IO.File]::Exists($probe)) {
            try { [IO.File]::Delete($probe) } catch { }
        }
    }
}

$applyButton.Add_Click({
    if ($script:managerOperation -ne 'Idle') { return }
    $operationTimer = New-Object Diagnostics.Stopwatch
    try {

    $applyConfirmed = $false
    $applySucceeded = $false
    $successText = ''
    try {
        $script:managerError = ''
        $script:managerNotice = ''
        $process = Get-HrsProcessState
        if ($process.Game -ne 'Closed') {
            if ($process.Game -eq 'Running') { throw 'Close 7 Days to Die before applying settings or uninstalling.' }
            throw 'Game state unavailable. Close 7 Days to Die and return here.'
        }

        $gameName = $gameNameBox.Text

        $nameCheck = Test-HrsExactGameName -GameName $gameName
        if (-not $nameCheck.Valid) {
            throw (Get-HrsNameHelp -Reason $nameCheck.Reason)
        }

        $paths = Get-HrsBridgePaths -GameRoot $gameRoot
        $current = Read-HrsConfiguredPolicy -GameRoot $gameRoot
        $revision = [UInt64]1
        if ($null -ne $current) {
            if ($current.revision -eq [UInt64]::MaxValue) { throw 'Policy revision is exhausted.' }
            $revision = [UInt64]$current.revision + 1
        }
        $mode = if (!$randomRadio.Checked) { 'Standard' } elseif ($biomeProtectCheck.Checked) { 'RandomSafe' } else { 'Random' }
        $selectionArgs = Get-HrsFormSelection
        $policy = New-HrsPolicy -Revision $revision -GameName $gameName -Mode $mode @selectionArgs
        $description = Get-HrsFormDescription
        $protection = if ($mode -eq 'RandomSafe') { 'On' } else { 'Off' }
        $gameBuildNotice = Get-HrsGameBuildNotice
        $protectionScope = if ($mode -ne 'Standard' -and $selectionArgs.Selection -ceq 'Chosen' -and $selectionArgs.ChosenBiome -eq 3) { "`r`nFresh Forest landing: no recognized HRS starting-hazard protection applies." } else { '' }
        $confirmationText = "Game Name for your save: $gameName`r`n$description`r`nStarting biome hazard protection: $protection$protectionScope`r`n`r`n"
        if ($mode -ne 'Standard') { $confirmationText += "If no safe landing is available, HRS keeps the usual start.`r`n" }
        $confirmationText += "Changing settings won't give existing characters another start.`r`nLaunch the game separately."
        if ($gameBuildNotice) { $confirmationText += "`r`n`r`n$gameBuildNotice" }
        $confirm = [Windows.Forms.MessageBox]::Show($form,
            $confirmationText,
            'Apply settings?',[Windows.Forms.MessageBoxButtons]::YesNo,[Windows.Forms.MessageBoxIcon]::Question,[Windows.Forms.MessageBoxDefaultButton]::Button2)
        if ($confirm -ne [Windows.Forms.DialogResult]::Yes) {
            $status.Text='Settings canceled - no change made'
            $script:managerNotice = $status.Text
            return
        }
        $applyConfirmed = $true
        Start-HrsManagerOperation -Operation Applying
        $operationTimer.Start()
        $script:launchBlockedUntilApply = $true
        $launchButton.Enabled = $false
        Initialize-HrsManagerStorage

        if (-not $useDevCandidate) {
            $verifiedDll = Join-Path $verifiedPayloadRoot 'd0163.dll'
            $verifiedModInfo = Join-Path $verifiedPayloadRoot 'ModInfo.xml'
            $assemblyCSharpPath = Join-Path $gameRoot '7DaysToDie_Data\Managed\Assembly-CSharp.dll'

            if (-not (Test-Path -LiteralPath $verifiedDll -PathType Leaf) -or
                -not (Test-Path -LiteralPath $verifiedModInfo -PathType Leaf)) {
                throw 'Verified mod payload is incomplete. Redownload the mod package.'
            }

            if (-not (Test-Path -LiteralPath $assemblyCSharpPath -PathType Leaf)) {
                throw 'Game compatibility check failed: Assembly-CSharp.dll was not found.'
            }

            $dllHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $verifiedDll).Hash

            if (-not [string]::Equals(
                $dllHash,
                $verifiedRuntimeSha256,
                [System.StringComparison]::Ordinal
            )) {
                throw 'Verified mod runtime hash mismatch. Do not install; redownload the mod package.'
            }

            $modInfoHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $verifiedModInfo).Hash
            if (-not [string]::Equals(
                $modInfoHash,
                $verifiedModInfoSha256,
                [System.StringComparison]::Ordinal
            )) {
                throw 'Verified mod ModInfo hash mismatch. Do not install; redownload the mod package.'
            }

            try {
                [xml]$modInfo = [System.IO.File]::ReadAllText($verifiedModInfo)

                $nameNode = @($modInfo.DocumentElement.ChildNodes | Where-Object {
                    [string]::Equals($_.Name, 'Name', [System.StringComparison]::Ordinal)
                }) | Select-Object -First 1

                $versionNode = @($modInfo.DocumentElement.ChildNodes | Where-Object {
                    [string]::Equals($_.Name, 'Version', [System.StringComparison]::Ordinal)
                }) | Select-Object -First 1

                if ($null -eq $nameNode -or $null -eq $versionNode) {
                    throw 'required identity node missing'
                }

                $modName = [string]$nameNode.GetAttribute('value')
                $modVersion = [string]$versionNode.GetAttribute('value')

                if (-not [string]::Equals(
                    $modName,
                    'BitWrecked_HistoricalRandomStart',
                    [System.StringComparison]::Ordinal
                )) {
                    throw 'mod identity mismatch'
                }

                if (-not [string]::Equals(
                    $modVersion,
                    '1.3.0',
                    [System.StringComparison]::Ordinal
                )) {
                    throw 'mod version mismatch'
                }
            }
            catch {
                throw 'Verified mod ModInfo identity validation failed. Do not install; redownload the mod package.'
            }

            $payloadRoot = $verifiedPayloadRoot
        }
        else {
            $buildScript = Join-Path $managerRoot 'src\runtime\p0143.ps1'

            if (-not (Test-Path -LiteralPath $buildScript -PathType Leaf)) {
                throw 'Alpha Core build script was not found.'
            }

            $status.Text = 'Building New Player Random Start release...'
            $form.Refresh()

            $buildRecord = & $buildScript -GameRoot $gameRoot

            if ($null -eq $buildRecord -or [string]::IsNullOrWhiteSpace([string]$buildRecord.candidateRoot)) {
                throw 'Build did not return a candidate release.'
            }

            $payloadRoot = Join-Path $buildRecord.candidateRoot 'mod'
        }

        $status.Text = 'Applying New Player Random Start settings...'
        $form.Refresh()
        $applied = Invoke-HrsInstallAndApply `
            -GameRoot $gameRoot `
            -PayloadRoot $payloadRoot `
            -Policy $policy `
            -ReleaseVersion '1.3.0'
        $script:appliedManifest = $applied.Manifest
        $script:appliedPayloadRoot = $payloadRoot
        $historyError = ''
        if ($null -ne $current -and $current.schema -ceq 'hrs-policy/v1') {
            try {
                [void](Add-HrsRecoveryAttempt -ManagerRoot $managerRoot -Outcome Succeeded `
                    -Reason LEGACY_BASELINE_CAPTURED -Policy $current -KnownGood)
            } catch { $historyError = $_.Exception.Message }
        }
        try {
            [void](Add-HrsRecoveryAttempt -ManagerRoot $managerRoot -Outcome Succeeded -Reason APPLY_SUCCEEDED -Policy $applied.Policy -KnownGood)
        } catch { $historyError = $_.Exception.Message }

        if ($mode -ne 'Standard') {
            $suffix = if ($mode -eq 'RandomSafe') { ' - Random start, starting-biome protection ON' } else { ' - Random start' }
            $status.Text = "Ready for $gameName$suffix"
        }
        else {
            $status.Text = "Ready for $gameName - Standard start"
        }
        if ($gameBuildNotice) { $status.Text += ' - untested game build' }
        if ($historyError) {
            $script:managerHistoryDiagnostic = $historyError
            $status.Text = 'Settings verified; recovery history could not be recorded. Keep Game details for support.'
            $script:managerNotice = $status.Text
        }
        Update-HrsStatus -RefreshInstallation
        Update-HrsResultStatus
        $traderSessionNotice = if ($mode -eq 'Standard') { '' } else {
            "Do not log out until your first trader is assigned. Complete the opening tasks in this session and wait for the Journey to Settlement trader marker. Leaving earlier may send the quest to Pine Forest when you return.`r`n`r`n"
        }
        $historyNotice = if ($historyError) { "Recovery history could not be recorded. Keep Game details for support.`r`n`r`n" } else { '' }
        $successText = "$traderSessionNotice" + "Settings applied and verified for: $gameName`r`n$description`r`nStarting biome hazard protection: $protection$protectionScope`r`n`r`n" +
            "$historyNotice" +
            'Click OK, then use Launch Game when Steam is running.'
        $applySucceeded = $true
        $operationTimer.Stop()
    }
    catch {
        $applyError = Get-HrsApplyErrorText -Detail $_.Exception.Message
        $operationTimer.Stop()
        if ($applyConfirmed) {
            try {
                [void](Add-HrsHistoryEvent -ManagerRoot $managerRoot -Action Apply -Outcome Failed `
                    -Reason APPLY_FAILED -GameName $gameName -Revision $revision -Mode $mode)
            } catch { }
        }
        $status.Text = "Settings blocked: $applyError"
        $script:managerError = "Settings blocked: $($_.Exception.Message)"
        $script:managerErrorAction = 'Apply'
        Update-HrsStatus -RefreshInstallation
        [System.Windows.Forms.MessageBox]::Show(
            $form,
            $applyError,
            'New Player Random Start',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        ) | Out-Null
    }
    if ($applySucceeded) {
        $script:managerOperation = 'AwaitingAcknowledgement'
        Update-HrsStatus
        $acknowledgement = [System.Windows.Forms.MessageBox]::Show(
            $form,
            $successText,
            'New Player Random Start - Settings Applied',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        )
        if ($acknowledgement -eq [System.Windows.Forms.DialogResult]::OK) {
            $script:launchBlockedUntilApply = $false
        } else {
            $script:managerNotice = 'Settings verified. Apply Settings and acknowledge Settings Applied before launching.'
        }
        Update-HrsStatus -RefreshInstallation
    }
    } finally {
        $operationTimer.Stop()
        $script:lastOperationDurationMs = $operationTimer.Elapsed.TotalMilliseconds
        $script:managerOperation = 'Idle'
        Update-HrsStatus -RefreshInstallation
    }
})



$launchButton.Add_Click({
    if ($script:managerOperation -ne 'Idle') { return }
    try {
        $configuredPolicy = Read-HrsConfiguredPolicy -GameRoot $gameRoot
        if ($null -eq $configuredPolicy -or $configuredPolicy.schema -cne 'hrs-policy/v2') {
            throw 'Apply Settings before launching. Enter the exact game name, choose your settings, then click Apply Settings.'
        }
        if ($script:launchBlockedUntilApply) {
            throw 'Apply Settings successfully and acknowledge Settings Applied before launching.'
        }
        if (!(Test-HrsFormMatchesPolicy -Policy $configuredPolicy)) {
            throw 'Changes not applied. Select Apply Settings before launching.'
        }
        if ($useDevCandidate) {
            if ($null -eq $script:appliedManifest) {
                throw 'Apply Settings in this DEV manager session before launching.'
            }
            $launchManifest = $script:appliedManifest
        }
        else {
            $verifiedDll = Join-Path $verifiedPayloadRoot 'd0163.dll'
            $verifiedModInfo = Join-Path $verifiedPayloadRoot 'ModInfo.xml'
            if (-not (Test-Path -LiteralPath $verifiedDll -PathType Leaf) -or
                -not (Test-Path -LiteralPath $verifiedModInfo -PathType Leaf) -or
                (Get-FileHash -Algorithm SHA256 -LiteralPath $verifiedDll).Hash -cne $verifiedRuntimeSha256 -or
                (Get-FileHash -Algorithm SHA256 -LiteralPath $verifiedModInfo).Hash -cne $verifiedModInfoSha256) {
                throw 'Verified mod payload changed. Redownload the mod package.'
            }
            $launchManifest = New-HrsDeploymentManifest -PayloadRoot $verifiedPayloadRoot -ReleaseVersion '1.3.0'
        }
        $launch = Test-HrsLaunchInstallation `
            -GameRoot $gameRoot `
            -Manifest $launchManifest `
            -ProcessState (Get-HrsProcessState)
        $gameBuildNotice = Get-HrsGameBuildNotice
        $script:managerError = ''
        $script:managerNotice = ''
        $status.Text = if ($gameBuildNotice) { 'Launching game - untested build; HRS will attempt compatible hooks.' } else { 'Launching game...' }
        Start-Process -FilePath $launch.Executable -WorkingDirectory $launch.WorkingDirectory -WindowStyle Normal
    }
    catch {
        $status.Text = "Launch blocked: $($_.Exception.Message)"
        $script:managerError = $status.Text
        $script:managerErrorAction = 'Launch'
        Update-HrsStatus -RefreshInstallation
        $customerError = Get-HrsCustomerErrorText -Detail $_.Exception.Message
        [System.Windows.Forms.MessageBox]::Show(
            $form,
            $customerError,
            'New Player Random Start',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        ) | Out-Null
    }
})



$uninstallButton.Add_Click({
    if ($script:managerOperation -ne 'Idle') { return }
    $operationTimer = New-Object Diagnostics.Stopwatch
    try {

    try {
        $process = Get-HrsProcessState

        if ($process.Game -ne 'Closed') {
            throw 'Close 7 Days to Die before uninstalling the mod.'
        }

        $ownership = Test-HrsRemovalOwnership -GameRoot $gameRoot

        if (-not $ownership.Valid) {
            throw "Uninstall blocked: $($ownership.Reason)"
        }

        if ($ownership.State -eq 'NotInstalled') {
            $status.Text = 'New Player Random Start is not installed'
            $script:managerNotice = $status.Text
            return
        }

        if ($ownership.State -ne 'Owned') {
            throw 'Uninstall blocked because the installed files could not be confirmed as New Player Random Start.'
        }

        $confirm = [System.Windows.Forms.MessageBox]::Show(
            $form,
            "Uninstall New Player Random Start from this game?`r`n`r`nHRS-owned files will be removed. Saves, player progress and unrelated files are preserved. This does not reset a saved landing or quest.",
            'Confirm Uninstall',
            [System.Windows.Forms.MessageBoxButtons]::YesNo,
            [System.Windows.Forms.MessageBoxIcon]::Warning,
            [System.Windows.Forms.MessageBoxDefaultButton]::Button2
        )

        if ($confirm -ne [System.Windows.Forms.DialogResult]::Yes) {
            $status.Text = 'Uninstall canceled - no change made'
            $script:managerNotice = $status.Text
            return
        }

        Start-HrsManagerOperation -Operation Uninstalling
        $operationTimer.Start()
        $process = Get-HrsProcessState
        $manifest = New-HrsDeploymentManifest `
            -PayloadRoot $verifiedPayloadRoot `
            -ReleaseVersion '1.3.0'

        $result = Invoke-HrsRemoveFromGame `
            -GameRoot $gameRoot `
            -Manifest $manifest `
            -ProcessState $process `
            -Confirmed

        if (-not $result.Removed) {
            throw 'Uninstall did not complete.'
        }
        $operationTimer.Stop()

        $script:appliedManifest = $null
        $script:appliedPayloadRoot = $null
        $script:managerError = ''
        $script:managerNotice = ''
        $script:launchBlockedUntilApply = $false
        Update-HrsStatus -RefreshInstallation
        $status.Text = 'New Player Random Start uninstalled'
        $script:managerNotice = $status.Text
        Update-HrsResultStatus
    }
    catch {
        $status.Text = "Uninstall blocked: $($_.Exception.Message)"
        $operationTimer.Stop()
        $script:managerError = $status.Text
        $script:managerErrorAction = 'Uninstall'
        Update-HrsStatus -RefreshInstallation
        $customerError = Get-HrsCustomerErrorText -Detail $_.Exception.Message

        [System.Windows.Forms.MessageBox]::Show(
            $form,
            $customerError,
            'New Player Random Start',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Warning
        ) | Out-Null
    }
    } finally {
        $operationTimer.Stop()
        $script:lastOperationDurationMs = $operationTimer.Elapsed.TotalMilliseconds
        $script:managerOperation = 'Idle'
        Update-HrsStatus -RefreshInstallation
    }
})
$form.Add_Activated({
    Update-HrsStatus -RefreshInstallation
    Update-HrsResultStatus
})
$form.Add_Shown({
    try {
        $saved = Read-HrsConfiguredPolicy -GameRoot $gameRoot
        if ($null -ne $saved) {
            Set-HrsFormFromPolicy -Policy $saved
        }
        Update-HrsBiomePreview
        Update-HrsStatus -RefreshInstallation
        Update-HrsResultStatus
    } catch {
        $script:managerError="Settings blocked: $($_.Exception.Message)"
        Update-HrsStatus -RefreshInstallation
    }
    Fit-HrsManagerWindow
    $gameNameBox.Focus()
})

$form.Add_FormClosing({ param($sender,$eventArgs); if ($script:managerOperation -ne 'Idle') { $eventArgs.Cancel=$true } })

$form.Add_Disposed({
    foreach ($font in $script:hrsOwnedFonts) { $font.Dispose() }
    if ($null -ne $script:hrsOwnedIcon) { $script:hrsOwnedIcon.Dispose() }
    if ($null -ne $script:hrsOwnedHeaderIcon) { $script:hrsOwnedHeaderIcon.Dispose() }
})
Initialize-HrsBiomeLayout
$script:managerInitialized = $true
$gameNameBox.Add_TextChanged({ if (!$script:loadingSelection) { $script:managerNotice = ''; Update-HrsStatus } })
$biomeProtectCheck.Add_CheckedChanged({ if (!$script:loadingSelection) { $script:managerNotice = ''; Update-HrsStatus } })
if ($SmokeTest) {
    $form.Show()
    [Windows.Forms.Application]::DoEvents()
    if ($UiScale -ne 1) { $form.Scale((New-Object Drawing.SizeF($UiScale,$UiScale))) }
    $saved=Read-HrsConfiguredPolicy -GameRoot $gameRoot
    if($null -ne $saved) {
        if($gameNameBox.Text -cne $saved.gameName){throw 'FORM_SAVED_NAME_FAILED'}
        $expected=Get-HrsSelectionArguments $saved
        if((Get-HrsFormSelection).Selection -cne $expected.Selection){throw 'FORM_SAVED_METHOD_FAILED'}
    }
    $before=@($biomes | ForEach-Object {$weights[$_]})
    Show-WeightEditor -TestAction Cancel
    if((@($biomes | ForEach-Object {$weights[$_]}) -join ',') -cne ($before -join ',')){throw 'EDITOR_CANCEL_CHANGED_WEIGHTS'}
    Show-WeightEditor -TestAction Save
    if($weights['Wasteland'] -ne 100 -or $weights['Forest'] -ne 0){throw 'EDITOR_SAVE_FAILED'}
    for($i=0;$i -lt 5;$i++){$weights[$biomes[$i]]=$before[$i]}
    $form.Height=[Math]::Min($form.Height,([Windows.Forms.Screen]::FromControl($form).WorkingArea.Height-20))
    $randomRadio.Checked=$true
    Set-HrsSelectionMethod -Selection Chosen
    $chosenCombo.SelectedItem='Snow'
    if ((Get-HrsFormSelection).ChosenBiome -ne 1) { throw 'FORM_CHOSEN_FAILED' }
    Set-HrsSelectionMethod -Selection Weighted
    $args=Get-HrsFormSelection
    if ($args.Weights.Count -ne 5 -or $args.Selection -cne 'Weighted') { throw 'FORM_WEIGHTS_FAILED' }
    Set-HrsSelectionMethod -Selection Any
    Set-HrsSelectionMethod -Selection Weighted
    if ((Get-HrsFormSelection).Weights[4] -ne $weights['Wasteland']) {throw 'FORM_RETAIN_WEIGHTS_FAILED'}
    if ($ScreenshotPath) {
        $bmp=New-Object Drawing.Bitmap($form.Width,$form.Height)
        try { $form.DrawToBitmap($bmp,(New-Object Drawing.Rectangle(0,0,$form.Width,$form.Height)));$bmp.Save($ScreenshotPath) } finally {$bmp.Dispose()}
        Show-WeightEditor -CapturePath ($ScreenshotPath -replace '\.png$','-weights.png')
    }
    $form.Dispose()
    'PASS: real manager controls and selection binding (no install/launch)'
    exit 0
}
[void]$form.ShowDialog()
